package com.americanmilestone.texport

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test

/**
 * The phone app must export byte-for-byte what the browser extension exports.
 * The expected files were generated by the extension's src/export.js from the same sample collection.
 */
class ExporterTest {
    private fun res(name: String) = javaClass.classLoader!!.getResource(name)!!.readText()
    private fun sample() = Json.parseFile(res("sample.texport.json"), "x", "2026-10-11T00:00:00Z")

    @Test fun matchesBrowserExtension_defaultOptions() {
        val md = Exporter.markdown(Exporter.build(sample()), ExportOptions(), "DATE")
        assertEquals(res("expected-both.md"), md)
    }

    @Test fun matchesBrowserExtension_endMarkedNoCounts() {
        val o = ExportOptions(placement = "end", content = "marked", counts = false, extra = "Answer in French.")
        assertEquals(res("expected-end-marked.md"), Exporter.markdown(Exporter.build(sample()), o, "DATE"))
    }

    @Test fun locateIsWhitespaceTolerant() {
        val t = "Gate 1 runs\n  build.py now"
        val p = Exporter.locate(t, "Gate 1 runs build.py")!!
        assertEquals("Gate 1 runs\n  build.py", t.substring(p[0], p[1]))
        assertNull(Exporter.locate("abc", "zzzz"))
    }

    @Test fun collectionFileRoundTrip() {
        val c = sample()
        val back = Json.parseFile(Json.serializeFile(c, "test", "2026-10-11T00:00:00Z"), "y", "2026-10-11T00:00:00Z")
        assertEquals(c.name, back.name)
        assertEquals(c.markerCount, back.markerCount)
        assertEquals(Exporter.build(c).total, Exporter.build(back).total)
    }

    @Test fun rejectsOtherFiles() {
        for (bad in listOf("nope", "{\"format\":\"other\"}", "{\"format\":\"texport.collection\",\"version\":2,\"collection\":{\"convos\":[]}}")) {
            try { Json.parseFile(bad, "z", "t"); fail("accepted: $bad") } catch (e: IllegalArgumentException) { assertTrue(e.message!!.isNotEmpty()) }
        }
    }

    @Test fun measureMatchesExtension() {
        assertEquals(Size(14, 3, 4), Measure.of("  one two  three "))
        assertEquals("1.5k", Measure.short(1530))
        assertEquals("25k", Measure.short(25400))
    }
}
